const bounded=(promise,ms,label)=>Promise.race([promise,sleep(ms).then(()=>({timeout:label}))]);

async function peerState(instance){const result=await instance.browser.executeAsync((done)=>{Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedSessionState.ts")]).then(async([{mockAdapter},{connectedStateFor}])=>{const s=await mockAdapter.getSnapshot();const st=connectedStateFor(mockAdapter);const r=s.resolution;done({role:s.session.role,connectionState:s.connectionState,mode:s.sessionMode,currentActorId:s.scene.currentActorId,cursor:st.replica?.cursor??st.ledger?.cursor??null,pendingRemote:Boolean(st.pendingRemoteAction),compatibilityMessage:s.session.compatibilityMessage,activeCharacterId:s.activeCharacter.id,slots:(s.scene.spellcastingByActor?.[s.activeCharacter.id]?.slots??[]).map((l)=>({level:l.level,current:l.current,max:l.max})),announcement:document.querySelector(".session-resolution-announcement")?.textContent??"",resolution:r?{id:r.id,stage:r.stage,actorId:r.actorId,actionName:r.actionName,targetIds:r.targetIds,dice:r.authoritativeDice,compact:r.compact,finalOutcome:r.finalOutcome,attackOutcome:r.attackOutcome,attackTotal:r.attackTotal,rollTotal:r.rollTotal,critical:r.critical,canAdvance:r.canAdvance,stateChanges:r.stateChanges,damageComponents:(r.damageComponents??[]).length,checkTarget:r.checkTarget,checkOutcome:r.checkOutcome,saves:(r.saveResults??[]).map((x)=>({targetId:x.targetId,targetName:x.targetName,total:x.total,dc:x.dc,outcome:x.outcome}))}:null,items:s.activeCharacter.items.map((i)=>({id:i.id,definitionId:i.definitionId,name:i.name,quantity:i.quantity,equipped:i.equipped})),inventory:(()=>{const inv=s.sessionCharacterInventories?.[s.activeCharacter.id];return inv?{revision:inv.revision,goldGp:inv.goldGp,items:inv.items.map((i)=>({id:i.id,definitionId:i.definitionId,name:i.name,quantity:i.quantity}))}:null;})(),activity:s.activity.slice(0,60).map((e)=>({id:e.id,actor:e.actor,title:e.title,summary:e.summary,stateChanges:e.stateChanges,detail:e.detail})),entities:s.scene.entities.map((e)=>({id:e.id,name:e.name,hp:e.hp,maxHp:e.maxHp,kind:e.kind,initiative:e.initiative??null,side:e.side,status:[...(e.status??[])]})),resources:(s.activeCharacter.resources??[]).map((x)=>({id:x.id,label:x.label,current:x.current,max:x.max})),hasCanvas:Boolean(document.querySelector("canvas"))});}).catch((error)=>done({error:String(error?.stack??error)}));});assert.ok(!result.error,result.error);return result;}
async function refreshShell(instance){await instance.browser.executeAsync((done)=>{Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedSessionRuntimeAdapter.ts")]).then(async([{mockAdapter},{publishConnectedSnapshot}])=>{await publishConnectedSnapshot(mockAdapter);done({ok:true});}).catch((error)=>done({error:String(error?.stack??error)}));});}
async function actions(instance,actorId){return instance.browser.executeAsync((actorId,done)=>{import("/src/app/mockAdapter.ts").then(async({mockAdapter})=>{const s=await mockAdapter.getSnapshot();done((s.scene.actionsByActor[actorId]??[]).map((a)=>({id:a.id,name:a.name,available:a.available,disabledReason:a.disabledReason,target:a.target,eligibleTargetIds:a.eligibleTargetIds,resolutionKind:a.resolutionKind,economy:a.economy,spellId:a.spellCast?.spellId??null,readyActionRole:a.readyActionRole??null,maxTargets:a.maxTargets??null})));}).catch((error)=>done({error:String(error?.stack??error)}));},actorId);}
async function findAction(instance,actorId,predicate,label){const list=await actions(instance,actorId);assert.ok(!list.error,list.error);const found=list.find(predicate);assert.ok(found,`${instance.label}: action ${label} not projected for ${actorId}; have ${list.map((a)=>a.name).join("|")}`);return found;}
const HOST_LEDGER_DIAG='const [{connectedStateFor},{decodeConnectedWireMessage}]=await Promise.all([import("/src/app/connectedSessionState.ts"),import("/src/app/connectedSessionWire.ts")]);const st=connectedStateFor(mockAdapter);if(!st.ledger)return null;const c=st.ledger.cursor;const events=st.ledger.eventsAfter(Math.max(0,c-3));const decoded=events.map((e)=>{const r=decodeConnectedWireMessage(JSON.stringify({type:"event-batch",sessionId:st.ledger.sessionId,afterCursor:e.sequence-1,events:[e]}));return {sequence:e.sequence,kind:e.payload.kind,decode:typeof r==="string"?r:"ok"};});return {cursor:c,decoded,events};';
async function hostCall(host,body,args){const result=await host.browser.executeAsync(new Function("args","done",`Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedSessionRuntimeAdapter.ts")]).then(async([{mockAdapter},{publishConnectedSnapshot}])=>{try{const out=await (async()=>{${body}})();await publishConnectedSnapshot(mockAdapter);done({ok:true,out});}catch(error){done({ok:false,error:String(error instanceof Error?error.message:error)});}}).catch((error)=>done({ok:false,error:String(error?.stack??error)}));`),args??{});assert.equal(result.ok,true,result.error);return result.out;}
const seenResolutionIds=new Set();
// Walks the authoritative Initiative to the actor's next fresh turn. If the actor is already current its turn economy may be spent, so the Host ends that turn first and cycles the order once.
async function peerCall(instance,body,args){const result=await instance.browser.executeAsync(new Function("args","done",`Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedSessionRuntimeAdapter.ts")]).then(async([{mockAdapter},{publishConnectedSnapshot}])=>{try{const out=await (async()=>{${body}})();await publishConnectedSnapshot(mockAdapter);done({ok:true,out});}catch(error){done({ok:false,error:String(error instanceof Error?error.message:error)});}}).catch((error)=>done({ok:false,error:String(error?.stack??error)}));`),args??{});assert.equal(result.ok,true,`${instance.label}: ${result.error}`);return result.out;}
// A created Cleric holds mace + shield; stowing the shield through the production inventory API frees the hand that somatic-only spells (Sacred Flame, Guiding Bolt, Cure Wounds) need.
async function stowShield(instance){return peerCall(instance,`const s=await mockAdapter.getSnapshot();const shield=s.activeCharacter.items.find((i)=>i.definitionId==="dnd.srd521.item.shield"&&i.equipped);if(!shield)return {stowed:false,items:s.activeCharacter.items.map((i)=>i.name+":"+(i.equipped?"E":"-")+(i.wielded?"W":"-"))};const after=await mockAdapter.toggleItemEquipped(shield.id);return {stowed:true,wielded:after.activeCharacter.items.filter((i)=>i.wielded).map((i)=>i.name+":"+i.wieldSlot)};`);}
async function paritySnapshot(instance,actorId){const result=await instance.browser.executeAsync((actorId,done)=>{import("/src/app/mockAdapter.ts").then(async({mockAdapter})=>{const s=await mockAdapter.getSnapshot();const e=s.scene.entities.find((x)=>x.id===actorId);const norm=(a)=>({id:a.id,name:a.name,category:a.category,economy:a.economy,target:a.target,available:a.available,resolutionKind:a.resolutionKind,eligibleTargetIds:[...(a.eligibleTargetIds??[])].sort(),maxTargets:a.maxTargets??null,spellId:a.spellCast?.spellId??null});const inv=s.sessionCharacterInventories?.[actorId];done({roster:s.scene.entities.map((x)=>({id:x.id,name:x.name,side:x.side,kind:x.kind})).sort((a,b)=>a.id<b.id?-1:1),actor:e?{id:e.id,name:e.name,hp:e.hp,maxHp:e.maxHp,tempHp:e.tempHp,ac:e.ac,status:[...e.status].sort(),initiative:e.initiative}:null,economy:s.scene.economyByActor[actorId]??null,currentActorId:s.scene.currentActorId,mode:s.sessionMode,actions:(s.scene.actionsByActor[actorId]??[]).map(norm).sort((a,b)=>a.id<b.id?-1:1),inventory:inv?{goldGp:inv.goldGp,items:inv.items.map((i)=>({id:i.id,definitionId:i.definitionId,name:i.name,quantity:i.quantity,equipped:i.equipped,wielded:i.wielded??false,wieldSlot:i.wieldSlot??null})).sort((a,b)=>a.id<b.id?-1:1)}:null});}).catch((error)=>done({error:String(error?.stack??error)}));},actorId);assert.ok(!result.error,result.error);return result;}
function actionParityDiff(hostActions,clientActions,{compareAvailability=true}={}){const byId=new Map(clientActions.map((a)=>[a.id,a]));const diffs=[];for(const h of hostActions){const c=byId.get(h.id);if(!c){diffs.push(`missing on client: ${h.id}`);continue;}for(const key of ["name","category","economy","target","resolutionKind","maxTargets","spellId",...(compareAvailability?["available"]:[])]){if(JSON.stringify(h[key])!==JSON.stringify(c[key]))diffs.push(`${h.id}.${key}: host=${JSON.stringify(h[key])} client=${JSON.stringify(c[key])}`);}if(JSON.stringify(h.eligibleTargetIds)!==JSON.stringify(c.eligibleTargetIds))diffs.push(`${h.id}.eligibleTargetIds: host=${JSON.stringify(h.eligibleTargetIds)} client=${JSON.stringify(c.eligibleTargetIds)}`);}for(const c of clientActions)if(!hostActions.some((h)=>h.id===c.id))diffs.push(`missing on host: ${c.id}`);return diffs;}
async function expectUiParity(host,client,actorId,label){const h=await paritySnapshot(host,actorId);const c=await paritySnapshot(client,actorId);assert.deepEqual(c.roster,h.roster,`${label}: roster diverges`);assert.deepEqual(c.actor,h.actor,`${label}: Actor projection diverges`);assert.deepEqual(c.economy,h.economy,`${label}: turn economy diverges`);assert.equal(c.currentActorId,h.currentActorId,`${label}: current Actor diverges`);const ownTurn=h.currentActorId===actorId;const diffs=actionParityDiff(h.actions,c.actions,{compareAvailability:ownTurn});assert.deepEqual(diffs,[],`${label}: action bar diverges: ${diffs.slice(0,12).join(" | ")}`);if(h.inventory&&c.inventory){assert.equal(c.inventory.goldGp,h.inventory.goldGp,`${label}: GP diverges`);assert.deepEqual(c.inventory.items,h.inventory.items,`${label}: inventory diverges`);}return {actions:h.actions.length,items:h.inventory?.items.length??null,goldGp:h.inventory?.goldGp??null,roster:h.roster.length,availabilityCompared:ownTurn,offTurnAvailability:ownTurn?null:{host:h.actions.filter((a)=>a.available).length,client:c.actions.filter((a)=>a.available).length}};}
async function walkToActor(host,actorId,{fresh=true}={}){const before=await peerState(host);if(before.mode!=="initiative")await hostCall(host,`await mockAdapter.startInitiative();`);else if(fresh&&before.currentActorId===actorId)await hostCall(host,`await mockAdapter.endTurn();`);for(let step=0;step<16;step+=1){const s=await peerState(host);if(s.currentActorId===actorId)return s;await hostCall(host,`await mockAdapter.endTurn();`);}const s=await peerState(host);throw new Error(`Host could not walk the initiative order to ${actorId}; current=${s.currentActorId} entities=${s.entities.map((e)=>e.id).join(",")}`);}
async function hostAdvanceToComplete(host,resolutionId){let last=null;for(let step=0;step<14;step+=1){last=await peerState(host);if(!last.resolution||last.resolution.id!==resolutionId)break;if(last.resolution.stage==="complete")return last;if(!last.resolution.canAdvance){await sleep(300);continue;}await hostCall(host,`await mockAdapter.advanceResolution();`);}last=await peerState(host);return last;}
async function clientAct(client,actionId,targetIds){return client.browser.executeAsync((actionId,targetIds,done)=>{Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedSessionRuntimeAdapter.ts")]).then(async([{mockAdapter},{publishConnectedSnapshot}])=>{try{const s=await mockAdapter.resolveAction(actionId,targetIds);await publishConnectedSnapshot(mockAdapter);done({ok:true,resolutionId:s.resolution?.id??null,stage:s.resolution?.stage??null,compatibilityMessage:s.session.compatibilityMessage});}catch(error){done({ok:false,error:String(error instanceof Error?error.message:error)});}}).catch((error)=>done({ok:false,error:String(error?.stack??error)}));},actionId,targetIds);}
async function waitHostResolutionFor(host,actorId,timeout=20_000){let last=null;await host.browser.waitUntil(async()=>{last=await peerState(host);return Boolean(last.resolution&&last.resolution.actorId===actorId&&!seenResolutionIds.has(last.resolution.id));},{timeout,interval:200,timeoutMsg:`Host did not start a new Resolution for ${actorId}; last=${JSON.stringify(last?.resolution)} msg=${last?.compatibilityMessage}`});seenResolutionIds.add(last.resolution.id);return last;}
async function waitActivityEntry(instance,resolutionId,timeout=20_000){let last=null;await instance.browser.waitUntil(async()=>{last=await peerState(instance);return last.activity.some((e)=>e.id===resolutionId);},{timeout,interval:200,timeoutMsg:`${instance.label} did not record ${resolutionId}; activity=${JSON.stringify(last?.activity?.map((e)=>e.id))} msg=${last?.compatibilityMessage}`});return last;}
async function openActivity(instance){const open=await instance.browser.$("aside.session-activity-pane");if(await open.isExisting())return;await click(instance.browser,exactButton("기록"),`${instance.label} 기록 패널`);await instance.browser.$("aside.session-activity-pane").waitForExist({timeout:10_000});}
async function closeActivity(instance){await instance.browser.keys("Escape");await sleep(200);}
async function renderedActivityText(instance){await openActivity(instance);const text=await instance.browser.$("aside.session-activity-pane").getText().catch(async()=>bodyText(instance));return text;}
function d20FaceOf(state,resolutionId){const entry=state.activity.find((e)=>e.id===resolutionId);const detail=(entry?.detail??[]).join("\n");const match=detail.match(/selected d20 (\d+)/);if(match)return Number(match[1]);const dice=state.resolution&&state.resolution.id===resolutionId?state.resolution.dice:[];return dice.length?dice[0]:null;}
function assertQueuedD20(state,resolutionId,face,label){const seen=d20FaceOf(state,resolutionId);assert.equal(seen,face,`${label}: authoritative d20 must be the queued ${face}; Host committed ${seen} (dice=${JSON.stringify(state.resolution?.dice)})`);}
function entity(state,id){return state.entities.find((e)=>e.id===id);}
const terminalView=(r)=>r?{id:r.id,stage:r.stage,actionName:r.actionName,actorId:r.actorId,targetIds:r.targetIds,attackOutcome:r.attackOutcome??null,attackTotal:r.attackTotal??null,rollTotal:r.rollTotal??null,finalOutcome:r.finalOutcome??null,compact:r.compact??null,critical:r.critical??null,checkOutcome:r.checkOutcome??null}:null;
async function waitClientTerminal(client,resolutionId,timeout=30_000){let last=null,announcement="";await client.browser.waitUntil(async()=>{last=await peerState(client);if(last.announcement&&last.announcement.length>announcement.length)announcement=last.announcement;const applied=last.activity.some((e)=>e.id===resolutionId);if(!applied)return false;const r=last.resolution;if(r&&r.id===resolutionId)return r.stage==="complete";return true;},{timeout,interval:200,timeoutMsg:`${client.label} did not reach the terminal presentation of ${resolutionId}; last=${JSON.stringify(last?.resolution)} msg=${last?.compatibilityMessage}`});return{state:last,announcement};}
async function expectConverged(peers,resolutionId,label){const host=await waitActivityEntry(peers[0],resolutionId);const hostEntry=host.activity.find((e)=>e.id===resolutionId);const states=[[peers[0].label,host]];const views=[];const announcements={};const clientEntries=[];for(const p of peers.slice(1)){const {state,announcement}=await waitClientTerminal(p,resolutionId);states.push([p.label,state]);announcements[p.label]=announcement;const e=state.activity.find((x)=>x.id===resolutionId);assert.ok(e,`${label}: ${p.label} has no committed entry`);clientEntries.push([p.label,{title:e.title,summary:e.summary,stateChanges:e.stateChanges}]);for(const he of host.entities){const pe=entity(state,he.id);if(pe)assert.equal(pe.hp,he.hp,`${label}: ${p.label} HP for ${he.name} diverges (${pe.hp} vs Host ${he.hp})`);}if(state.resolution&&state.resolution.id===resolutionId)views.push([p.label,terminalView(state.resolution)]);}for(const [name,entry] of clientEntries.slice(1))assert.deepEqual(entry,clientEntries[0][1],`${label}: ${name} committed entry diverges from ${clientEntries[0][0]}`);if(views.length>=2){for(const [name,view] of views.slice(1))assert.deepEqual(view,views[0][1],`${label}: ${name} terminal resolution view diverges from ${views[0][0]}`);}assert.ok(hostEntry,`${label}: Host has no committed entry`);states.announcements=announcements;states.views=views;return states;}
async function evidenceAll(peers,suffix){for(const p of peers)await bounded(saveEvidence(p,suffix).catch(()=>undefined),15_000,"evidence");}

function crashInstance(instance){if(!instance.child.pid)return;spawnSync("taskkill",["/PID",String(instance.child.pid),"/T","/F"],{stdio:"inherit",windowsHide:true});instance.crashed=true;}
async function participantIdFor(host,characterName){const snapshot=await runtimeSnapshot(host);const participant=snapshot.participants.find((entry)=>entry.characterName===characterName);assert.ok(participant,`Host has no participant for ${characterName}; participants=${JSON.stringify(snapshot.participants)}`);return participant.id;}
async function waitConnection(instance,expected,timeout=45_000){let last=null;await instance.browser.waitUntil(async()=>{last=await peerState(instance);return expected.includes(last.connectionState);},{timeout,interval:300,timeoutMsg:`${instance.label} did not reach ${expected.join("/")}; last=${last?.connectionState} msg=${last?.compatibilityMessage}`});return last;}
async function rejoinClient(label,dataRoot,characterId,sessionPort){const instance=await launchInstance(label,dataRoot,await reservePort());await selectProductionCharacter(instance,characterId);await joinClientSession(instance,sessionPort);return instance;}
async function expectCaughtUp(host,client,resolutionIds,label){const h=await peerState(host);const s=await waitActivityEntry(client,resolutionIds[resolutionIds.length-1]);for(const id of resolutionIds)assert.ok(s.activity.some((e)=>e.id===id),`${label}: ${client.label} is missing committed ${id}`);const positions=resolutionIds.map((id)=>s.activity.findIndex((e)=>e.id===id));for(let i=1;i<positions.length;i+=1)assert.ok(positions[i]<positions[i-1],`${label}: ${client.label} applied events out of order (${JSON.stringify(positions)})`);for(const he of h.entities){const pe=entity(s,he.id);if(pe)assert.equal(pe.hp,he.hp,`${label}: ${client.label} HP for ${he.name} diverges (${pe.hp} vs Host ${he.hp})`);}assert.equal(s.cursor,h.cursor,`${label}: ${client.label} cursor ${s.cursor} must equal Host ${h.cursor}`);return s;}
async function ensureGoblin(host){return hostCall(host,`const initial=await mockAdapter.getSnapshot();const existing=initial.scene.entities.find((e)=>e.id.startsWith("local.w9.h.goblin.instance-"));if(existing)return existing.id;const campaign=initial.campaigns?.find((entry)=>entry.name==="W7-05 Hidden Roll")??initial.campaigns?.[0];if(!campaign)throw new Error("W9-02H Campaign was not found");const entry={entryId:"w9.h.goblin",kind:"npc-definition",label:"W9 고블린",definitionId:"local.w9.h.goblin",favorite:false,tags:["W9-02H"],npcDefinition:{definitionId:"local.w9.h.goblin",name:"고블린",nameEn:"Goblin",ac:15,maxHp:40,actions:["시미터","숏보우"],statusImmunities:[],source:"W9-02H",version:"1",runtimeStats:{abilities:{str:8,dex:14,con:10,int:10,wis:8,cha:8},proficiencyBonus:2,savingThrowProficiencies:[],speed:30,resistances:[],immunities:[],vulnerabilities:[]},runtimeActions:[{id:"scimitar",name:"시미터",category:"weapon",sourceKind:"weapon",attackBonus:4,rangeFeet:5,damage:{type:"참격",dice:"1d6",flat:2}},{id:"shortbow",name:"숏보우",category:"weapon",sourceKind:"weapon",attackBonus:4,rangeFeet:80,damage:{type:"관통",dice:"1d6",flat:2}}]}};await mockAdapter.upsertCampaignDmLibraryEntry(campaign.campaignId,entry);const snapshot=await mockAdapter.instantiateCampaignDmLibraryNpcDefinition(campaign.campaignId,entry.entryId);const npc=snapshot.scene.entities.find((e)=>e.id.startsWith("local.w9.h.goblin.instance-"));if(!npc)throw new Error("goblin NPC did not enter the Host Scene");return npc.id;`);}

async function runScenario(){
  assert.equal(process.platform,"win32","W9-02 Tauri acceptance is Windows-only");assert.ok(existsSync(binary),`Tauri E2E binary was not found: ${binary}`);
  await rm(runRoot,{recursive:true,force:true});await mkdir(artifactRoot,{recursive:true});await ensureVite();
  const sessionPort=await reservePort();const hostRoot=path.join(runRoot,"host","data");const p1Root=path.join(runRoot,"p1","data");const p2Root=path.join(runRoot,"p2","data");const p3Root=path.join(runRoot,"p3","data");
  let host=await launchInstance("W9-02H Host",hostRoot,await reservePort());let p1=await launchInstance("W9-02H P1",p1Root,await reservePort());let p2=await launchInstance("W9-02H P2",p2Root,await reservePort());let p3=null;
  const live=()=>[host,p1,p2,p3].filter((p)=>p&&!p.crashed);const scenarios={};const record=(id,data)=>{scenarios[id]={status:"PASS",...data};log(`${id} PASS`);};
  const fighter1=await createDistinctPlayerCharacter(p1,"W9 Fighter One");const fighter2=await createDistinctPlayerCharacter(p2,"W9 Fighter Two");
  await createHostCampaign(host);await openHostSession(host,sessionPort);await joinClientSession(p1,sessionPort);await joinClientSession(p2,sessionPort);
  await host.browser.waitUntil(async()=>(await peerState(host)).entities.filter((e)=>e.kind==="character").length>=2,{timeout:20_000,timeoutMsg:"H/P1/P2 Characters did not enter the Host Scene"});
  let goblinId=await ensureGoblin(host);
  for(const p of [p1,p2])await p.browser.waitUntil(async()=>Boolean(entity(await peerState(p),goblinId)),{timeout:15_000,timeoutMsg:`${p.label} did not receive the NPC topology`});
  await hostCall(host,`await mockAdapter.startInitiative();`);
  for(const p of [p1,p2])await p.browser.waitUntil(async()=>(await peerState(p)).mode==="initiative",{timeout:15_000,timeoutMsg:`${p.label} did not enter Initiative`});
  await evidenceAll(live(),"w9-02h-setup");
  const committed=[];let hostRes=null;
  const attack=async(face,label)=>{await walkToActor(host,fighter1.id);await hostCall(host,`await mockAdapter.setQueuedD20(${face});`);const greatsword=await findAction(p1,fighter1.id,(a)=>a.name.startsWith("대검")&&a.available,`greatsword (${label})`);const sent=await clientAct(p1,greatsword.id,[goblinId]);assert.equal(sent.ok,true,sent.error);hostRes=await waitHostResolutionFor(host,fighter1.id);const done=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(done.resolution?.stage,"complete",`${label}: ${JSON.stringify(done.resolution)}`);committed.push(done.resolution.id);return done;};
  try{
    // MP-H01: P2 disconnects before an action; P1 acts and H commits; P2 relaunches on the same data root, rejoins, and catches up without a cinematic flood.
    const p2Participant=await participantIdFor(host,fighter2.name);
    crashInstance(p2);await waitParticipantState(host,p2Participant,"disconnected",30_000);
    const rosterAfterLeave=(await peerState(host)).entities.map((e)=>e.id);
    const h01=await attack(15,"MP-H01");await expectConverged([host,p1],h01.resolution.id,"MP-H01 live");
    p2=await rejoinClient("W9-02H P2 (rejoined)",p2Root,fighter2.id,sessionPort);
    const h01Caught=await expectCaughtUp(host,p2,[h01.resolution.id],"MP-H01");await sleep(800);
    const h01Canvas=(await peerState(p2)).hasCanvas;assert.equal(h01Canvas,false,"a rejoining peer must not replay old cinematics");
    await evidenceAll(live(),"w9-02h-h01");record("MP-H01",{resolutionId:h01.resolution.id,rosterWhileAway:rosterAfterLeave,cursor:h01Caught.cursor});

    // MP-H02: P2 disconnects during the shared dice presentation; the committed result reaches it after rejoin as a terminal catch-up.
    await walkToActor(host,fighter1.id);await hostCall(host,`await mockAdapter.setQueuedD20(16);`);
    const greatsword=await findAction(p1,fighter1.id,(a)=>a.name.startsWith("대검")&&a.available,"greatsword (MP-H02)");
    const h02Sent=await clientAct(p1,greatsword.id,[goblinId]);assert.equal(h02Sent.ok,true,h02Sent.error);
    hostRes=await waitHostResolutionFor(host,fighter1.id);await p2.browser.waitUntil(async()=>{const s=await peerState(p2);return Boolean(s.resolution&&s.resolution.id===hostRes.resolution.id);},{timeout:15_000,timeoutMsg:"P2 did not start presenting the live roll"});
    const p2ParticipantB=await participantIdFor(host,fighter2.name);crashInstance(p2);
    const h02Done=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(h02Done.resolution?.stage,"complete",JSON.stringify(h02Done.resolution));committed.push(h02Done.resolution.id);
    await waitParticipantState(host,p2ParticipantB,"disconnected",30_000);await expectConverged([host,p1],h02Done.resolution.id,"MP-H02 live");
    p2=await rejoinClient("W9-02H P2 (rejoined 2)",p2Root,fighter2.id,sessionPort);
    const h02Caught=await expectCaughtUp(host,p2,[h01.resolution.id,h02Done.resolution.id],"MP-H02");await sleep(800);assert.equal((await peerState(p2)).hasCanvas,false,"catch-up must not replay the interrupted cinematic");
    await evidenceAll(live(),"w9-02h-h02");record("MP-H02",{resolutionId:h02Done.resolution.id,cursor:h02Caught.cursor});

    // MP-H03: P1 disconnects after sending an intent and before H commits it; H settles the pending action explicitly and P1 converges after rejoin.
    await walkToActor(host,fighter1.id);await hostCall(host,`await mockAdapter.setQueuedD20(14);`);
    const gs3=await findAction(p1,fighter1.id,(a)=>a.name.startsWith("대검")&&a.available,"greatsword (MP-H03)");
    const h03Sent=await clientAct(p1,gs3.id,[goblinId]);assert.equal(h03Sent.ok,true,h03Sent.error);
    hostRes=await waitHostResolutionFor(host,fighter1.id);const p1Participant=await participantIdFor(host,fighter1.name);
    crashInstance(p1);await waitParticipantState(host,p1Participant,"disconnected",30_000);
    const h03Settled=await hostAdvanceToComplete(host,hostRes.resolution.id);const h03Committed=h03Settled.resolution?.id===hostRes.resolution.id&&h03Settled.resolution.stage==="complete";
    await sleep(1500);const h03Host=await peerState(host);assert.equal(h03Host.pendingRemote,false,`Host must not keep a pending action for a departed owner; msg=${h03Host.compatibilityMessage}`);
    if(h03Committed)committed.push(hostRes.resolution.id);
    p1=await rejoinClient("W9-02H P1 (rejoined)",p1Root,fighter1.id,sessionPort);
    const h03Caught=await expectCaughtUp(host,p1,committed.slice(-2),"MP-H03");
    const h03After=await attack(12,"MP-H03 after rejoin");await expectConverged(live(),h03After.resolution.id,"MP-H03 after rejoin");
    await evidenceAll(live(),"w9-02h-h03");record("MP-H03",{pendingResolutionId:hostRes.resolution.id,settled:h03Committed?"committed":"discarded",hostMessage:h03Host.compatibilityMessage,cursor:h03Caught.cursor,afterRejoin:h03After.resolution.id});

    // MP-H04 + MP-H05: H crashes while a remote action is pending; H restarts with durable Campaign state, reopens the Session, and the Clients reconnect; the uncommitted action is gone everywhere.
    await walkToActor(host,fighter1.id);await hostCall(host,`await mockAdapter.setQueuedD20(13);`);
    const gs4=await findAction(p1,fighter1.id,(a)=>a.name.startsWith("대검")&&a.available,"greatsword (MP-H04)");
    const h04Sent=await clientAct(p1,gs4.id,[goblinId]);assert.equal(h04Sent.ok,true,h04Sent.error);
    hostRes=await waitHostResolutionFor(host,fighter1.id);const pendingId=hostRes.resolution.id;const cursorBeforeCrash=hostRes.cursor;
    crashInstance(host);
    for(const p of [p1,p2])await waitConnection(p,["reconnecting","disconnected"],30_000);
    host=await launchInstance("W9-02H Host (restarted)",hostRoot,await reservePort());
    const durable=await runtimeSnapshot(host);assert.ok(durable.campaignId,`the Campaign must survive the Host restart; got ${JSON.stringify(durable)}`);
    const campaignName=await hostCall(host,`const s=await mockAdapter.getSnapshot();return (s.campaigns??[]).map((c)=>c.name);`);assert.ok(campaignName.includes("W7-05 Hidden Roll"),`durable Campaign list: ${JSON.stringify(campaignName)}`);
    await openHostSession(host,sessionPort);
    for(const p of [p1,p2]){try{await waitConnection(p,["connected"],45_000);}catch(error){log(`${p.label} did not auto-reconnect (${error instanceof Error?error.message:error}); rejoining through the Session screen`);await joinClientSession(p,sessionPort);}}
    for(const name of [fighter1.name,fighter2.name])await waitParticipantState(host,await participantIdFor(host,name),"connected",30_000);
    const h05Host=await peerState(host);assert.equal(h05Host.pendingRemote,false,"restarted Host must not resurrect the uncommitted action");assert.ok(!h05Host.activity.some((e)=>e.id===pendingId),"the uncommitted action must not appear as committed history");
    goblinId=await ensureGoblin(host);for(const p of [p1,p2])await p.browser.waitUntil(async()=>Boolean(entity(await peerState(p),goblinId)),{timeout:20_000,timeoutMsg:`${p.label} did not receive the restarted Host topology`});
    if((await peerState(host)).mode!=="initiative"){await hostCall(host,`await mockAdapter.startInitiative();`);for(const p of [p1,p2])await p.browser.waitUntil(async()=>(await peerState(p)).mode==="initiative",{timeout:15_000,timeoutMsg:`${p.label} did not re-enter Initiative`});}
    const h04After=await attack(11,"MP-H04 after restart");await expectConverged(live(),h04After.resolution.id,"MP-H04 after restart");
    for(const p of [p1,p2])assert.ok(!(await peerState(p)).activity.some((e)=>e.id===pendingId),`${p.label} must not carry the uncommitted action as history`);
    await evidenceAll(live(),"w9-02h-h04");record("MP-H04",{pendingResolutionId:pendingId,cursorBeforeCrash,afterRestart:h04After.resolution.id});record("MP-H05",{campaigns:campaignName,campaignId:durable.campaignId,sessionReopened:true});

    // MP-H08: a stale Client cursor is rejected explicitly; the Client catches up and the next intent commits.
    await walkToActor(host,fighter1.id);
    const stale=await p1.browser.executeAsync((actionId,targetId,done)=>{Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedSessionState.ts"),import("/src/app/connectedSessionRuntimeAdapter.ts"),import("/src/app/tauriSessionTransport.ts")]).then(async([{mockAdapter},{connectedStateFor},{connectedManifest,CONNECTED_CAPABILITIES},{tauriSessionTransport}])=>{const state=connectedStateFor(mockAdapter);const character=connectedManifest(mockAdapter).character;const request={sessionId:state.sessionId,requestId:`request.w9h.stale.${Date.now().toString(36)}`,actorId:character.characterId,actionId,targetIds:[targetId],knownEventCursor:Math.max(0,state.replica.cursor-1),character,capabilities:[...CONNECTED_CAPABILITIES]};await tauriSessionTransport.send(JSON.stringify({type:"action-request",request}));done({ok:true,sentCursor:request.knownEventCursor,cursor:state.replica.cursor});}).catch((error)=>done({ok:false,error:String(error?.stack??error)}));},(await findAction(p1,fighter1.id,(a)=>a.name.startsWith("대검"),"greatsword (MP-H08)")).id,goblinId);assert.equal(stale.ok,true,stale.error);
    let staleMessage="";await p1.browser.waitUntil(async()=>{staleMessage=(await peerState(p1)).compatibilityMessage??"";return /stale/i.test(staleMessage);},{timeout:15_000,timeoutMsg:`P1 did not receive the stale-cursor rejection; msg=${staleMessage}`});
    const cursorH08=(await peerState(host)).cursor;await sleep(800);assert.equal((await peerState(host)).cursor,cursorH08,"a stale intent must not commit");assert.equal((await peerState(host)).pendingRemote,false);
    const h08After=await attack(17,"MP-H08 after catch-up");await expectConverged(live(),h08After.resolution.id,"MP-H08 after catch-up");
    await evidenceAll(live(),"w9-02h-h08");record("MP-H08",{sentCursor:stale.sentCursor,clientCursor:stale.cursor,rejection:staleMessage,afterCatchUp:h08After.resolution.id});

    // MP-H06 + MP-J07: P2 leaves for good and P3 late-joins after several more actions; final state and Activity catch up in order without flooding.
    const p2ParticipantC=await participantIdFor(host,fighter2.name);crashInstance(p2);await waitParticipantState(host,p2ParticipantC,"disconnected",30_000);
    const h06a=await attack(12,"MP-H06 a");await expectConverged([host,p1],h06a.resolution.id,"MP-H06 a");const h06b=await attack(18,"MP-H06 b");await expectConverged([host,p1],h06b.resolution.id,"MP-H06 b");
    p3=await launchInstance("W9-02H P3",p3Root,await reservePort());const fighter3=await createDistinctPlayerCharacter(p3,"W9 Fighter Three");await joinClientSession(p3,sessionPort);
    await host.browser.waitUntil(async()=>Boolean(entity(await peerState(host),fighter3.id)),{timeout:20_000,timeoutMsg:"P3's Character did not enter the Host Scene"});
    const h06Caught=await expectCaughtUp(host,p3,[h06a.resolution.id,h06b.resolution.id],"MP-H06");await sleep(800);assert.equal((await peerState(p3)).hasCanvas,false,"a late joiner must not replay old cinematics");
    const rosterHost=(await peerState(host)).entities.map((e)=>e.id).sort();const rosterP1=(await peerState(p1)).entities.map((e)=>e.id).sort();const rosterP3=(await peerState(p3)).entities.map((e)=>e.id).sort();
    assert.deepEqual(rosterP1,rosterHost,"P1 roster must converge after the late join");assert.deepEqual(rosterP3,rosterHost,"P3 roster must converge on join");
    await evidenceAll(live(),"w9-02h-h06");record("MP-H06",{caughtUp:[h06a.resolution.id,h06b.resolution.id],cursor:h06Caught.cursor});record("MP-J07",{roster:rosterHost,p2Left:fighter2.id,p3Joined:fighter3.id});
  }catch(error){await evidenceAll(live(),"w9-02h-failure");const diag={};for(const p of live())diag[p.label]=await bounded(peerState(p).catch((e)=>({error:String(e)})),8_000,"state");diag.hostLedger=await bounded(hostCall(host,HOST_LEDGER_DIAG).catch((e)=>({error:String(e)})),8_000,"ledger");await writeFile(path.join(artifactRoot,"w9-02h-failure-state.json"),`${JSON.stringify({scenarios,diag},null,2)}\n`,"utf8").catch(()=>undefined);throw new Error(`${error instanceof Error?error.message:String(error)}; passed=${Object.keys(scenarios).join(",")} states=${JSON.stringify(diag).slice(0,3000)}`);}
  const evidence={gate:"W9-02",family:"H",scope:Object.keys(scenarios),status:"PASS",verificationSha,windowsTauri:true,topology:{host:"DM Host (restarted once)",clients:["P1","P2 (rejoined twice, then left)","P3 (late join)"],npc:goblinId,sessionPort},scenarios};
  await writeFile(path.join(artifactRoot,"w9-02h-summary.json"),`${JSON.stringify(evidence,null,2)}\n`,"utf8");log(`PASS evidence: ${path.join(artifactRoot,"w9-02h-summary.json")}`);
}

async function cleanup(){if(keepOpen){log(`--keep-open active. Evidence: ${artifactRoot}`);return;}for(const browser of [...browsers].reverse()){try{await browser.deleteSession();}catch{}}for(const child of [...children].reverse()){if(child.exitCode===null&&!child.killed){try{child.kill();}catch{}}}if(viteStarted)log("Vite process stopped with tracked child cleanup.");}

let exitCode=0;try{await runScenario();}catch(error){exitCode=1;console.error(error instanceof Error?error.stack??error.message:error);try{await writeFile(path.join(artifactRoot,"w9-02h-failure.txt"),`${String(error instanceof Error?error.stack??error.message:error)}\n`,"utf8");}catch{}}finally{await cleanup();}process.exitCode=exitCode;
